from zoneinfo import ZoneInfo
import pandas as pd
from sqlalchemy import create_engine,text
ROOT=Path(__file__).resolve().parents[2]
sys.path[:0]=[str(ROOT),str(ROOT/'backend')]
from app.config import get_settings
OUT=ROOT/'artifacts/nifty_forecast_v3/2026-11-17/run-001'
OLD=ROOT/'artifacts/nifty_forecast/2026-11-17'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def save(name,value):
    p=OUT/name;p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(json.dumps(value,indent=2,default=str,allow_nan=False),encoding='utf-8')
def main():
    OUT.mkdir(parents=True,exist_ok=True)
    if (OUT/'legacy-review.json').exists():raise FileExistsError('Audit already frozen')
    review=[]
    paths=list((ROOT/'research/nifty_forecast').glob('*'))+list(ROOT.glob('NIFTY_*2026-11-17.md'))+list(OLD.rglob('*'))
    for p in paths:
        if not p.is_file() or p.suffix not in ['.py','.md','.json','.csv']:continue
        r={'path':str(p.relative_to(ROOT)),'sha256':sha(p),'bytes':p.stat().st_size}
        try:
            if p.suffix=='.py':
                source=p.read_text(encoding='utf-8');tree=ast.parse(source)
                r.update(functions=[n.name for n in ast.walk(tree) if isinstance(n,(ast.FunctionDef,ast.ClassDef))],lines=len(source.splitlines()))
            elif p.suffix=='.json':
                obj=json.loads(p.read_text(encoding='utf-8'));r.update(type=type(obj).__name__,keys=list(obj)[:35] if isinstance(obj,dict) else None,items=len(obj) if hasattr(obj,'__len__') else None)
            elif p.suffix=='.csv':
                f=pd.read_csv(p);r.update(rows=len(f),columns=list(f.columns),missing_cells=int(f.isna().sum().sum()))
            else:r['text']=p.read_text(encoding='utf-8')
        except Exception as exc:r['error']=str(exc)[:180]
        review.append(r)
    save('legacy-review.json',review)
    eng=create_engine(get_settings().database_url_sync,connect_args={'connect_timeout':8})
    queries={
        'schema':"SELECT table_name,column_name,data_type FROM information_schema.columns WHERE table_schema='public' ORDER BY table_name,ordinal_position",
        'datasets':"SELECT * FROM market_datasets LIMIT 1000",
        'coverage':"SELECT * FROM candle_coverage LIMIT 10000",
        'responses':"SELECT method,count(*) AS captures,min(fetched_at),max(fetched_at) FROM market_responses GROUP BY method",
        'factors':"SELECT factor_id,count(*) AS n,min(observed_at),max(observed_at),min(reported_at),max(reported_at) FROM nifty_observations GROUP BY factor_id",
        'chain_schema':"SELECT table_name,column_name,data_type FROM information_schema.columns WHERE table_name IN ('market_stream_chains','market_stream_ticks','market_responses','candle_coverage') ORDER BY table_name,ordinal_position",
        'events':"SELECT event_at,observed_at,payload FROM nifty_research_events WHERE event_at>='2025-01-01' ORDER BY event_at LIMIT 500",
    }
    database={}
    for name,q in queries.items():
        try:
            with eng.connect() as c:
                c.execute(text('SET statement_timeout=15000'));database[name]=[dict(r) for r in c.execute(text(q)).mappings()]
        except Exception as exc:database[name]={'error':type(exc).__name__,'detail':str(exc).splitlines()[0][:180]}
    eng.dispose();save('database-inventory.json',database)
    save('audit-start.json',{'issued_at':datetime.now(ZoneInfo('Asia/Kolkata')).isoformat(),'constraint':'2025-2026 only; no pre-2025 market values or fitted state in V3','legacy_artifacts_reviewed':len(review),'prior_forecast_hashes':{str(p.relative_to(ROOT)):sha(p) for p in OLD.glob('*/forecast.json')}})
    print(json.dumps({'reviewed':len(review),'database_inventory':{k:len(v) if isinstance(v,list) else v for k,v in database.items()}}),flush=True)
if __name__=='__main__':main()

"""Bounded exposed-history calibration and weekly tree stress diagnostics."""
import joblib
import numpy as np
import pandas as pd
from scipy.optimize import minimize_scalar
from scipy.special import expit,logit
from .common import *
from research.nifty_forecast_v3.models import train,predict,SPECS
from research.nifty_forecast_v3.experiment import summarize,nonoverlap,paired_ci

def direction_metrics(frame):
    p=frame.p.to_numpy();y=frame.outcome.to_numpy();pc=np.clip(p,1e-6,1-1e-6);pred=p>=.5
    bins=[]
    for lo,hi in [(0,.35),(.35,.45),(.45,.55),(.55,.65),(.65,1.00001)]:
        m=(p>=lo)&(p<hi)
        if m.any():bins.append({'lo':lo,'hi':min(hi,1),'n':int(m.sum()),'predicted':float(p[m].mean()),'observed':float(y[m].mean())})
    return {'n':len(y),'brier':float(np.mean((p-y)**2)),'log_loss':float(np.mean(-y*np.log(pc)-(1-y)*np.log(1-pc))),
        'accuracy':float(np.mean(pred==y)),'balanced_accuracy':float(np.mean([np.mean(pred[y==v]==v) for v in [0,1] if (y==v).any()])),
        'bins':bins,'up_frequency':float(y.mean())}

def run():
    if (OUT/'weekly-stress-predictions.csv').exists():raise FileExistsError('Study already exists')
    registry=read('registry.json');x,labels,frame=load();outer=frame[(frame.horizon==5)&(frame.split=='outer_exposed')]
    baseline=outer.pivot(index='origin',columns='model',values='brier').sort_index()
    audit={'frozen_metrics':{},'slices':[],'phase_nonoverlap':[],'leave_one_month_out':[],'exceptional_origin_sensitivity':[],'family_gains':[]}
    for name in ['M05_lgbm','A00_sector','Z_reversion','Z_neutral','B00_empirical']:
        data=outer[outer.model==name].sort_values('origin');audit['frozen_metrics'][name]=direction_metrics(data)
        for var in ['fold','regime','trend_regime','breadth_regime','expiry_regime','global_riskoff','large_prior_move']:
            for val,g in data.groupby(var):audit['slices'].append({'model':name,'variable':var,'value':str(val),**direction_metrics(g)})
        for offset in range(5):audit['phase_nonoverlap'].append({'model':name,'phase':offset,**direction_metrics(nonoverlap(data.iloc[offset:]))})
    delta=baseline.Z_reversion-baseline.M05_lgbm
    for month in sorted(outer.fold.unique()):
        days=outer[(outer.fold!=month)&(outer.model=='M05_lgbm')].origin
        audit['leave_one_month_out'].append({'removed_month':month,'n':len(days),'brier_improvement_vs_reversion':float(delta.reindex(days).mean())})
    for k in [1,3,5,10]:audit['exceptional_origin_sensitivity'].append({'remove_best_origins':k,'remaining_mean_improvement':float(delta.sort_values().iloc[:-k].mean()),'note':'Overlapping origins, not independent periods'})
    calibrations=[];stresses=[];calfit=[]
    for fold,g0 in outer[outer.model=='M05_lgbm'].groupby('fold'):
        daylist=list(g0.origin)
        for name in ['M05_lgbm','A00_sector']:
            artifact=joblib.load(V3/'models'/f'h5-{fold}-{name}.joblib');ix=artifact['train_idx'];fit=artifact['inner_train_idx'];val=artifact['inner_validation_idx']
            inner=train(SPECS[name],x.loc[fit],labels[5].loc[fit]);pv=np.array([p['p'] for p in predict(inner,x.loc[val])]);yv=labels[5].loc[val,'return'].gt(0).to_numpy()
            objective=lambda b:float(np.sum(np.logaddexp(0,logit(pv)+b)-yv*(logit(pv)+b))+10*b*b/2)
            offset=float(minimize_scalar(objective,bounds=(-1,1),method='bounded').x)
            base=float(labels[5].loc[ix[-252:],'return'].gt(0).mean());data=outer[(outer.model==name)&(outer.fold==fold)]
            for r in data.itertuples():
                for method,p in [('RAW',r.p),('SHRINK50',.5*r.p+.5*base),('OFFSET',float(expit(logit(r.p)+offset)))]:calibrations.append({'fold':fold,'origin':r.origin,'endpoint':r.endpoint,'model':name,'method':method,'p':p,'outcome':r.outcome,'raw_p':r.p,'base_rate':base})
            calfit.append({'fold':fold,'model':name,'offset':offset,'inner_n':len(val),'inner_nonoverlap_n':len(nonoverlap(pd.DataFrame({'origin':val,'endpoint':labels[5].loc[val,'endpoint'].to_numpy()}))),'inner_up_frequency':float(yv.mean()),'outer_up_frequency':float(data.outcome.mean()),'base_rate':base})
        original=joblib.load(V3/'models'/f'h5-{fold}-M05_lgbm.joblib');ix=original['train_idx']
        model=original['model'];cols=model['pre'].columns;gains=model['direction_model'].feature_importance('gain')
        for fam in sorted({c.split('_')[0] for c in cols}):audit['family_gains'].append({'fold':fold,'family':fam,'gain':float(sum(v for c,v in zip(cols,gains) if c.startswith(fam+'_'))),'note':'Training gain, not causal or validated incremental importance'})
        for variant in registry['lgbm_stress_variants']:
            xx=x if variant=='rolling126' else x.drop(columns=[c for c in x if c.startswith(variant[5:]+'_')]);training=ix[-126:] if variant=='rolling126' else ix
            fitted=train(SPECS['M05_lgbm'],xx.loc[training],labels[5].loc[training]);pred=predict(fitted,xx.loc[daylist])
            for r,p in zip(g0.itertuples(),pred):stresses.append({'fold':fold,'origin':r.origin,'endpoint':r.endpoint,'model':variant,'p':p['p'],'outcome':r.outcome})
        print('LightGBM/calibration diagnostics',fold,flush=True)
    cal=pd.DataFrame(calibrations);stress=pd.DataFrame(stresses);cal.to_csv(OUT/'calibration-predictions.csv',index=False);stress.to_csv(OUT/'weekly-stress-predictions.csv',index=False)
    audit['stress_metrics']=[{'variant':name,**direction_metrics(g)} for name,g in stress.groupby('model')]
    calmetrics=[]
    for (name,method),g in cal.groupby(['model','method']):
        flip=(g.p>=.5)!=(g.raw_p>=.5)
        calmetrics.append({'model':name,'method':method,**direction_metrics(g),'threshold_flips':int(flip.sum()),'correct_to_wrong':int((flip&((g.raw_p>=.5)==g.outcome)).sum()),'wrong_to_correct':int((flip&((g.p>=.5)==g.outcome)).sum()),'activation':'DISABLED; diagnostic only'})
    save('weekly-lightgbm-audit.json',audit);save('calibration-metrics.json',calmetrics);save('calibration-fit-ledger.json',calfit)
    print('Saved bounded diagnostic results',flush=True)
if __name__=='__main__':run()

"""Finite endpoint distributions: every statistic uses the same weighted atoms."""
import numpy as np
from scipy.stats import t
from .common import *
from research.nifty_forecast_v3.models import train,predict,SPECS

BUCKETS=np.array([-.05,-.02,-.005,.005,.02,.05])
class Distribution:
    def __init__(self,atoms,weights=None):
        a=np.asarray(atoms,float);w=np.ones(len(a)) if weights is None else np.asarray(weights,float)
        if not len(a) or not np.isfinite(a).all() or (a<=-1).any() or not np.isfinite(w).all() or (w<0).any() or w.sum()<=0:raise ValueError('INVALID_DISTRIBUTION')
        order=np.argsort(a);self.a=a[order];self.w=w[order]/w.sum()
    def quantile(self,q):return self.a[np.minimum(np.searchsorted(np.cumsum(self.w),q,side='left'),len(self.a)-1)]
    def stats(self,reference=1.):
        a,w=self.a,self.w;p=float(w[a>0].sum());mean=float(w@a);q=self.quantile(np.array([.05,.1,.25,.5,.75,.9,.95]))
        buckets=np.bincount(np.digitize(a,BUCKETS),weights=w,minlength=7)
        return {'p_up':p,'p_nonpositive':1-p,'mean_return':mean,'median_return':float(q[3]),
            'quantiles':dict(zip(['q05','q10','q25','q50','q75','q90','q95'],map(float,q))),
            'buckets':buckets.tolist(),'expected_endpoint':reference*(1+mean),'median_endpoint':reference*(1+float(q[3])),
            'interval50':(reference*(1+q[[2,4]])).tolist(),'interval80':(reference*(1+q[[1,5]])).tolist(),
            'expected_absolute_return':float(w@abs(a)),'endpoint_return_std':float(np.sqrt(w@((a-mean)**2))),
            'path_breach_probability':None,'future_realized_volatility':None,
            'path_note':'UNAVAILABLE: endpoint-only law does not identify paths or future realized volatility'}
    def score(self,y):
        s=self.stats();p=s['p_up'];yc=int(y>0);pc=float(np.clip(p,1e-6,1-1e-6))
        q=self.quantile(np.array([.1,.25,.5,.75,.9]));levels=np.array([.1,.25,.5,.75,.9]);truth=np.zeros(7);truth[np.digitize(y,BUCKETS)]=1
        crps=float(self.w@abs(self.a-y)-np.sum(self.w*self.a*(2*np.cumsum(self.w)-self.w-1)))
        return {'p':p,'outcome':yc,'realized_return':float(y),'predicted_mean':s['mean_return'],'predicted_median':s['median_return'],
            'brier':(p-yc)**2,'log_loss':-yc*np.log(pc)-(1-yc)*np.log(1-pc),'mae':abs(s['mean_return']-y),
            'squared_error':(s['mean_return']-y)**2,'median_mae':abs(s['median_return']-y),'crps':crps,
            'pinball':float(np.mean(np.maximum(levels*(y-q),(levels-1)*(y-q)))),
            'bucket_brier':float(np.sum((np.array(s['buckets'])-truth)**2)),
            'coverage50':int(q[1]<=y<=q[3]),'coverage80':int(q[0]<=y<=q[4]),'width50':float(q[3]-q[1]),'width80':float(q[4]-q[0]),
            **{f'bucket{i}_p':v for i,v in enumerate(s['buckets'])},'bucket_y':int(np.digitize(y,BUCKETS))}

def prepare(x,labels,training,innerfit,innerval):
    full=train(SPECS['A00_sector'],x.loc[training],labels.loc[training])
    inner=train(SPECS['A00_sector'],x.loc[innerfit],labels.loc[innerfit])
    residual=labels.loc[innerval,'return'].to_numpy()-np.array([p['mean'] for p in predict(inner,x.loc[innerval])])
    pool=labels.loc[training[-252:],'return'].to_numpy()
    return {'full':full,'residual':residual,'pool':pool,'trainx':x.loc[training[-252:]],'rv_median':float(x.loc[training[-252:],'price_rv21'].median())}

def forecast(context,row,h):
    y=context['pool'];n=len(y);x=context['trainx'];res=context['residual']
    mask=(x.price_ret21.gt(0).to_numpy()==bool(row.price_ret21>0))&(x.price_rv21.gt(context['rv_median']).to_numpy()==bool(row.price_rv21>context['rv_median']))
    weights=np.full(n,30/n)+mask.astype(float)
    mu=.5*predict(context['full'],row.to_frame().T)[0]['mean']+.5*float(y.mean())
    scale=max(float(np.sqrt(np.mean(res**2))),.005*np.sqrt(h/5))*np.sqrt(3/5)
    atoms=mu+scale*t.ppf((np.arange(501)+.5)/501,df=5)
    return {'D00_empirical':Distribution(y),'D01_regime_shrunk':Distribution(y,weights),
        'D02_student_shrunk':Distribution(np.maximum(atoms,-.999999)),
        'D03_residual_shrunk':Distribution(np.maximum(mu+res,-.999999))}

def summarize(g):
    result={'n':len(g),'accuracy':float(((g.p>=.5)==g.outcome).mean()),'rmse':float(np.sqrt(g.squared_error.mean()))}
    for c in ['brier','log_loss','mae','median_mae','crps','pinball','bucket_brier','coverage50','coverage80','width50','width80']:result[c]=float(g[c].mean())
    result['bucket_calibration']=[{'bucket':i,'predicted':float(g[f'bucket{i}_p'].mean()),'observed':float((g.bucket_y==i).mean())} for i in range(7)]
    return result

def run():
    if (OUT/'distribution-predictions.csv').exists():raise FileExistsError('Do not overwrite a completed study')
    read('registry.json');x,labels,v3=load();records=[];fits=[]
    from research.nifty_forecast_v3.experiment import available,inner_split,nonoverlap
    # Identical prequential origins and monthly boundaries, including development.
    for h in [5,21]:
        origins=v3[(v3.horizon==h)&(v3.model=='B00_empirical')]
        for fold,g in origins.groupby('fold'):
            training=available(labels[h],g.origin.min());innerfit,innerval=inner_split(labels[h],training)
            context=prepare(x,labels[h],training,innerfit,innerval)
            fits.append({'horizon':h,'fold':fold,'last_training_endpoint':str(labels[h].loc[training,'endpoint'].max()),'query_first':g.origin.min(),'inner_first':innerval[0],'inner_fit_last_endpoint':str(labels[h].loc[innerfit,'endpoint'].max()),'residual_count':len(context['residual'])})
            for r in g.itertuples():
                for name,d in forecast(context,x.loc[r.origin],h).items():
                    records.append({'horizon':h,'fold':fold,'origin':r.origin,'endpoint':r.endpoint,'split':r.split,'model':name,**d.score(r.realized_return)})
            print('Coherent distributions',h,fold,flush=True)
    frame=pd.DataFrame(records);frame.to_csv(OUT/'distribution-predictions.csv',index=False)
    metrics=[]
    for (h,split,name),g in frame.groupby(['horizon','split','model']):metrics.append({'horizon':int(h),'split':split,'model':name,**summarize(g),'disjoint':summarize(nonoverlap(g))})
    save('distribution-metrics.json',metrics);save('distribution-fit-ledger.json',fits)
    print('Saved coherent endpoint records',len(frame),flush=True)
if __name__=='__main__':run()

"""Single-writer, hash-chained append-only research events. No trade APIs."""
import os,json
from pathlib import Path
from .common import canonical,digest,now,OUT,ROOT,sha

def events(path):
    path=Path(path)
    if not path.exists():return []
    result=[];previous='0'*64;keys=set()
    for line in path.read_text(encoding='utf-8').splitlines():
        row=json.loads(line);signed={k:v for k,v in row.items() if k!='hash'}
        if row['previous_hash']!=previous or row['hash']!=digest(signed):raise ValueError('LEDGER_TAMPER_OR_PARTIAL_WRITE')
        key=(row['kind'],row['key'])
        if key in keys:raise ValueError('DUPLICATE_EVENT')
        keys.add(key);previous=row['hash'];result.append(row)
    return result

def append(path,kind,key,payload):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True);lock=path.with_suffix('.lock')
    fd=os.open(lock,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
    try:
        os.close(fd);old=events(path)
        if any(e['kind']==kind and e['key']==key for e in old):raise ValueError('DUPLICATE_EVENT')
        row={'sequence':len(old)+1,'kind':kind,'key':key,'created_at':now(),'previous_hash':old[-1]['hash'] if old else '0'*64,'payload':payload}
        row['hash']=digest(row);blob=canonical(row)+b'\n'
        fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_APPEND,0o600)
        try:
            offset=0
            while offset<len(blob):offset+=os.write(fd,blob[offset:])
            os.fsync(fd)
        finally:os.close(fd)
        return row
    finally:lock.unlink()

def verify_files(event):
    for name,expected in event['payload'].get('files',{}).items():
        p=(ROOT/name).resolve()
        if not p.is_relative_to(ROOT) or not p.is_file() or sha(p)!=expected:raise ValueError('ARTIFACT_CHANGED: '+name)

def resolution_eligible(forecast,now_stamp):
    from datetime import datetime,time
    from .common import TZ
    endpoint=forecast['expected_endpoint']
    return datetime.fromisoformat(now_stamp)>=datetime.combine(datetime.fromisoformat(endpoint).date(),time(18),TZ)

"""Fixed-clock market-data capture, immutable prediction issuance, later resolution."""
from __future__ import annotations
import argparse,json,shutil,time,uuid,sys
from datetime import datetime,timedelta,time as walltime
from email.utils import parsedate_to_datetime
from urllib.parse import quote
from pathlib import Path
import numpy as np
import pandas as pd
import requests,joblib
from .common import *
